mapper.select:
select * from (
    select sm.*, m.machine_code, m.machine_name
    from T_TQ_SPECIFY_MACHINE sm
    left join T_TQ_MACHINE_INFO m on sm.machine_id = m.id
    where sm.DEL_FLAG = 0
    and m.DEL_FLAG = 0

        and INSTR(sm.BEAD_CODE, #{beadCode}) > 0


        and sm.MACHINE_ID = #{machineId}


        and sm.LINE_TYPE = #{lineType}


        and sm.JOB_TYPE = #{jobType}


        order by sm.create_time desc

) t

    order by ${orderStr}
